-- CraveGo Bangalore demo dataset
-- Requires MySQL 8+ and the existing CraveGo schema.
-- Creates 21 users, 30 restaurants, 450 menu rows, 60 orders and 180 order items.
USE cravego;

SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE order_items;
TRUNCATE TABLE orders;
TRUNCATE TABLE menu;
TRUNCATE TABLE restaurants;
TRUNCATE TABLE users;
SET FOREIGN_KEY_CHECKS = 1;


CREATE TEMPORARY TABLE restaurant_seed (
  name VARCHAR(150), cuisine_type VARCHAR(100), delivery_time INT,
  address VARCHAR(255), rating DECIMAL(2,1), image_path VARCHAR(500)
);

SELECT rs.name, rs.cuisine_type, rs.delivery_time, rs.address, u.user_id, rs.rating, TRUE, rs.image_path
FROM restaurant_seed rs
JOIN users u ON u.email = 'admin@cravego.com';
DROP TEMPORARY TABLE restaurant_seed;


DROP PROCEDURE IF EXISTS seed_cravego_orders;
DELIMITER $$
CREATE PROCEDURE seed_cravego_orders()
BEGIN
  DECLARE i INT DEFAULT 0;
  DECLARE selected_user_id INT;
  DECLARE selected_restaurant_id INT;
  DECLARE generated_order_id INT;
  DECLARE user_offset INT;
  DECLARE restaurant_offset INT;

  WHILE i < 60 DO
    SET user_offset = i MOD 20;
    SET restaurant_offset = i MOD 30;

    SELECT user_id INTO selected_user_id
    FROM users WHERE role = 'CUSTOMER' ORDER BY user_id LIMIT user_offset, 1;

    SELECT restaurant_id INTO selected_restaurant_id
    FROM restaurants ORDER BY restaurant_id LIMIT restaurant_offset, 1;

    VALUES (
      selected_user_id, selected_restaurant_id, DATE_SUB(NOW(), INTERVAL i DAY), 0,
      CASE (i MOD 5)
        WHEN 0 THEN 'DELIVERED' WHEN 1 THEN 'PREPARING' WHEN 2 THEN 'PLACED'
        WHEN 3 THEN 'OUT_FOR_DELIVERY' ELSE 'CANCELLED' END,
      CASE (i MOD 3) WHEN 0 THEN 'CASH_ON_DELIVERY' WHEN 1 THEN 'UPI' ELSE 'CARD' END
    );

    SET generated_order_id = LAST_INSERT_ID();

    SELECT generated_order_id, menu_id, 1 + ((menu_id + i) MOD 2),
           price * (1 + ((menu_id + i) MOD 2))
    FROM menu
    WHERE restaurant_id = selected_restaurant_id
    ORDER BY menu_id
    LIMIT 3;

    UPDATE orders
    SET total_amount = (SELECT COALESCE(SUM(total_amount), 0) FROM order_items WHERE order_id = generated_order_id)
    WHERE order_id = generated_order_id;

    SET i = i + 1;
  END WHILE;
END$$
DELIMITER ;
CALL seed_cravego_orders();
DROP PROCEDURE seed_cravego_orders;

-- Verification: expected counts are 21, 30, 450, 60 and 180.
SELECT COUNT(*) AS users_count FROM users;
SELECT COUNT(*) AS restaurants_count FROM restaurants;
SELECT COUNT(*) AS menu_count FROM menu;
SELECT COUNT(*) AS orders_count FROM orders;
SELECT COUNT(*) AS order_items_count FROM order_items;
SELECT restaurant_id, COUNT(*) AS menu_items FROM menu GROUP BY restaurant_id ORDER BY restaurant_id;
